svg.script:
(function(){
  var m=document.getElementById("m");
  var src=new URL("SpacePad.html",location.href).href;
  fetch(src,{cache:"no-cache"}).then(function(r){
    if(!r.ok)throw new Error("HTTP "+r.status);
    return r.arrayBuffer();
  }).then(function(buf){
    var url=URL.createObjectURL(new Blob([buf],{type:"text/html;charset=utf-8"}));
    location.replace(url);
  }).catch(function(e){m.textContent="Could not load SpacePad.html: "+e.message;});
})();
